async function lobby(room) {
  const maps = await listMaps(), horde = room.mode === 'horde' ? await hordeMaps() : undefined;
  const saves = listSaves(saves_dir(), room.code).map(s => ({ id: s.id, kind: s.kind, savedAt: s.savedAt, mode: s.mode, minutes: s.minutes, names: s.names, world: s.world }));
  everyone(room).forEach((p) => { const i = room.players.indexOf(p); send(p.ws, {
    role: p.role ?? 'commander', commander: p.role === 'operative' ? room.players.indexOf(p.commander) : undefined, operatives: (room.operatives ?? []).map(o => ({ name: o.name, commander: room.players.indexOf(o.commander), online: connected(o) })), spectator: i < 0 && p.role !== 'operative', amHost: isHost(room, p), spectators: room.spectators.map(s => s.name),
    listed: !!room.listed, saves,
    hordeMaps: horde, hordeBest: room.mode === 'horde' ? recordOf(room) : null,
    t: 'lobby', code: room.code, state: room.state, you: i, host: hostOf(room), maps, mapName: room.mode === 'world' ? 'world' : room.mapName, spawns: seats(room), publicUrl: PUBLIC_URL,
    mode: room.mode, worldSize: room.worldSize ?? 'huge', defenderTeam: room.defenderTeam, army: room.army ?? 'standard', weather: room.weather ?? 'map', sandbox: !!room.sandbox,
    // a finished match's result carries this player's own outcome (you); a match the host ended has none
    result: room.result ? { ...room.result, you: room.result.story && i >= 0 ? p.lastMatch ?? null : null } : null,
    players: room.players.map(q => ({ name: q.name, connected: connected(q) || !!q.ai, ai: !!q.ai, team: q.team, faction: q.faction, level: q.ai ? q.level ?? 'normal' : null })),
  }); });

function scheduleSeatCleanup(room, player) {
  clock.clearTimeout(player.cleanupTimer);
  player.cleanupTimer = clock.setTimeout(() => {
    if (player.ws || player.ai || room.state !== 'lobby' || !room.players.includes(player)) return;
    retainSeats(room, room.players.filter(p => p !== player));
    lobby(room);
  }, 10_000);

ws.on('message', async (raw) => {
  let msg;
  try { msg = JSON.parse(raw); } catch { return; }
  if (!msg || typeof msg !== 'object') return;
  if (!me) {
    if (msg.t !== 'hello' || typeof msg.token !== 'string' || typeof msg.name !== 'string') return;
    room = rooms.get(code);
    if (!room && rooms.size >= MAX_ROOMS) { send(ws, { t: 'full', reason: 'capacity' }); return ws.close(); }
    // the Tutorial button makes a private room that starts the tutorial as soon as its player is in
    const tutorial = !room && msg.listing?.tutorial === true;
    if (!room) rooms.set(code, room = { code, listed: msg.listing?.public === true && !tutorial, title: (typeof msg.listing?.title === 'string' ? msg.listing.title : 'Open skirmish').replace(/[<>&"'\x00-\x1f]/g, '').trim().slice(0, 48) || 'Open skirmish', players: [], spectators: [], state: 'lobby', game: null, mode: tutorial ? 'tutorial' : 'conquest', defenderTeam: 0, matchId: 0, mapName: tutorial ? 'tutorial' : 'default', mapSpawns: tutorial ? TUTORIAL_SPAWNS : MAP.spawns });
    const token = String(msg.token || '').slice(0, 40), name = cleanName(msg.name);
    me = everyone(room).find(p => p.token === token && token);
    if (me) {
      const old = me.ws;
      clock.clearTimeout(me.cleanupTimer);
      me.ws = ws; me.name = name;
      if (room.game && room.players.includes(me) && !me.ai) { resetAI(room.game, room.players.indexOf(me)); resetCommander(room.game, room.players.indexOf(me)); }
      if (old && old !== ws) { send(old, { t: 'replaced' }); old.close(); }

  else if (msg.role === 'operative') {
    const commander = Number.isInteger(msg.commander) && room.players[msg.commander];
    if (!commander || commander.ai || (room.operatives ?? []).length >= 4 || !token || room.mode === 'world') { send(ws, { t: 'deny', cmd: 'join', reason: 'commander' }); return ws.close(1008, 'operative needs human commander; world mode unsupported'); }
    (room.operatives ??= []).push(me = { token, name, ws, role: 'operative', commander });
  }
  else if (room.state === 'lobby' && room.players.length < MAX_PLAYERS && (!room.listed || room.players.length < seats(room)) && msg.spectate !== true) addSeat(room, me = newPlayer(room, { token, name, ws }));
  else if (room.spectators.length < MAX_SPECTATORS) room.spectators.push(me = { token, name, ws }); // no seat to take, or asked to watch
  else { send(ws, { t: 'full', reason: room.state === 'play' ? 'started' : 'seats' }); return ws.close(); }
  room.emptySince = null;
  lobby(room);
  if (room.state !== 'lobby' && room.game) me.role === 'operative' ? sendOperativeStart(room, me) : room.players.includes(me) ? sendStart(room, room.players.indexOf(me)) : sendStart(room, 0, me);
  if (room.pause?.reason === 'drop' && room.pause.player === me) resumeRoom(room);
  if (tutorial && room.players[0] === me) await startMatch(room);
  return;
}
const slot = room.players.indexOf(me), seated = slot >= 0, host = isHost(room, me);
if (me.ws !== ws || (!seated && !room.spectators.includes(me) && !(room.operatives ?? []).includes(me))) return; // a replaced socket may still be open for a moment; a freed seat has no slot

if (msg.t === 'ping') {
  if ('x' in msg || 'z' in msg) return mapPing(room, me, slot, msg, send);
  if (Number.isFinite(msg.rtt)) me.rtt = Math.min(9999, Math.max(0, Math.round(msg.rtt)));
  if (diag) { me.diagAt = Date.now(); me.diagClient = cleanClient(msg.d); }
  // srv, for the stats overlay (client/stats.js): the slowest 5% of recent ticks that sent a snapshot in ms (the
  // number the tick meter holds to its 40 ms budget) and the ticks between snapshots
  const meter = room.state === 'play' && room.tickMeter;
  return send(ws, { t: 'pong', c: msg.c, ...(meter && { srv: [Math.round(tickStats(meter).snapshotTick.p95 * 10) / 10, room.snapEvery] }) });
}
if (me.role === 'operative') {
  if (msg.t === 'fps' && room.state === 'play' && room.game && !room.pause) {
    const now = clock.now();
    if (now - (me.inputAt ?? 0) >= 20) { me.inputAt = now; operativeInput(room.game, me.token, msg); }
  } else if (msg.t === 'resync' && me.net) me.net.full = true;
  else if (msg.t === 'name' && typeof msg.name === 'string') { me.name = cleanName(msg.name); lobby(room); }
  return; // No army orders, host powers, seat changes or full-map spectator fallback.
}
if (msg.t === 'name' && typeof msg.name === 'string') { me.name = cleanName(msg.name); lobby(room); }

} else if (msg.t === 'spectate' && seated && room.state === 'lobby' && room.spectators.length < MAX_SPECTATORS) {
  retainSeats(room, room.players.filter(p => p !== me)); room.spectators.push(me); lobby(room); // give up the seat and watch
} else if (msg.t === 'sit' && !seated && room.state === 'lobby' && room.players.length < MAX_PLAYERS && (!room.listed || room.players.length < seats(room))) {
  room.spectators = room.spectators.filter(s => s !== me); addSeat(room, Object.assign(me, newPlayer(room, me))); lobby(room);
} else if (msg.t === 'leave' && seated && room.state === 'play' && !me.ai) {
  // an AI takes over your army so the match goes on for the others; you can join the lobby again afterwards
  handToAi(room, me);
  send(ws, { t: 'left' }); ws.close();
} else if (seated && room.state === 'play' && room.game && !room.pause) {
  const reason = command(room.game, slot, msg);
  if (reason && allowDeny(me, clock.now())) send(ws, { t: 'deny', cmd: msg.t, reason });

// Keep denial traffic bounded per player, including across reconnects.
export function allowDeny(player, now = Date.now()) {
  const recent = (player.denyTimes ?? []).filter(t => now - t < 1000);
  player.denyTimes = recent;
  if (recent.length >= 4) return false;
  recent.push(now);
  return true;
}

// Server: a replaced or departed socket cannot keep controlling its old player slot.
await check("Server", async () => {
  const h = await serverHarness(), code = 'replaced';
  const old = await h.connect(code, { token: 'host', name: 'Old' });
  const current = await h.connect(code, { token: 'host', name: 'Current' });
  await old.late({ t: 'name', name: 'Stale' });
  assert.equal(current.lobby().players[0].name, 'Current', 'server replaced socket cannot rename its former player');
  await h.connect(code, { token: 'guest', name: 'Guest' });
  await current.send({ t: 'start' }); await current.wait('start');
  const before = h.game(code).units.size;
  await current.send({ t: 'leave' });
  await current.late({ t: 'buy', unit: 'rifle' });
  assert.equal(h.game(code).units.size, before, 'server departed socket cannot buy for the AI that took over');
  await h.close();

// Server: JSON objects masquerading as names or tokens cannot crash text conversion.
await check("Server", async () => {
  const h = await serverHarness(), code = 'badtext', invalid = { toString: null, valueOf: null };
  const p = await h.connect(code, { hello: false });
  for (const field of ['token', 'name']) {
    await p.send({ t: 'hello', token: 'host', name: 'Host', [field]: invalid });
    assert.equal(p.messages.length, 0, 'server malformed hello text does not claim a player slot');
    assert.equal(p.closed, false, `server malformed hello ${field} does not throw`);
  }
  await p.send({ t: 'hello', token: 'host', name: 'Host' }); await p.wait('lobby');
  await p.send({ t: 'name', name: invalid });
  assert.equal(p.closed, false, 'server malformed rename does not throw');
  assert.equal(p.lobby().players[0].name, 'Host', 'server malformed rename preserves the player name');
  await h.close();

await check(async code => {
  const [ana, ben] = await humans(code), room = await start(code, ana), player = room.players[0], matchId = room.matchId;
  assert.ok(Number.isSafeInteger(matchId) && matchId > 0, 'start identifies the match');
  const replacement = await h.connect(code, { token: ana.token, name: 'Ana' });
  await ana.wait('replaced'); await h.settleServer();
  assert.equal(ana.closed, true, 'the replaced socket is closed after its message');
  assert.equal(room.players[0], player, 'replacement keeps the same player object');
  assert.equal(room.pause, null, 'replacement does not trigger a drop pause');
  assert.equal((await replacement.wait('start')).matchId, matchId, 'same-match reconnect keeps its match id');

await check(async code => {
  const [ana] = await humans(code, ['Ana']);
  const { MAX_PLAYERS } = await import('./shared/sim.js');
  for (let i = 1; i < MAX_PLAYERS; i++) await ana.send({ t: 'addAi' });
  const invite = await h.connect(code, { token: code + 'invite', name: 'Invite' });
  assert.equal(last(invite, 'lobby').spectator, true, 'a full lobby seats nobody else: the invite watches');
  assert.equal(last(invite, 'lobby').you, -1, 'a spectator has no seat');
  for (let i = 1; i < 8; i++) await h.connect(code, { token: code + 'watch' + i, name: 'Watch' });
  const full = await h.connect(code, { token: code + 'late', name: 'Late' });
  assert.equal(last(full, 'full').reason, 'seats', 'a room with eight spectators turns the next one away');

// Spectators: a late invite watches the running match with the fog lifted, commands nothing and can sit down afterwards.
await check(async code => {
  const [ana, ben] = await humans(code), room = await start(code, ana);
  const invite = await h.connect(code, { token: code + 'invite', name: 'Invite' });
  assert.equal(last(invite, 'lobby').spectator, true, 'an invite cannot claim a new seat during play: it watches');
  const begin = await invite.wait('start');
  assert.equal(begin.you, 0, 'a spectator watches from the first seat');
  assert.equal(begin.fog, undefined, 'a spectator gets no fog mask');
  const after = invite.messages.length; await h.tick(2);
  const seen = await invite.wait('s', () => true, after);
  assert.equal(seen.units.length, room.game.units.size, 'a spectator sees every unit');
  assert.equal(seen.fog, undefined, 'a spectator gets no fog changes');
  assert.ok(last(ana, 's').units.length < seen.units.length, 'the seat it watches from still sees only its own side');
  const tick = room.game.tick;
  await invite.send({ t: 'leave' }); await invite.send({ t: 'end' }); await invite.send({ t: 'pause' }); await invite.send({ t: 'stop', ids: [...room.game.units.keys()] });
  assert.ok(room.state === 'play' && !room.pause && room.players.every(p => !p.ai), 'a spectator cannot leave for a player, end or pause the match');
  assert.ok(!last(invite, 'deny'), 'the orders of a spectator are dropped without an answer');
  await h.tick(); assert.equal(room.game.tick, tick + 1, 'the match runs on');
  // Lobby replies can trail the fixed server settle on a busy machine: wait for the reply each assertion reads.
  let before = invite.messages.length;
  await ben.close(); await ana.send({ t: 'end' });
  assert.equal((await invite.wait('lobby', m => m.state === 'lobby', before)).state, 'lobby', 'the spectator is back in the lobby with everyone');
  before = invite.messages.length;
  await invite.send({ t: 'sit' });
  assert.equal((await invite.wait('lobby', m => m.spectator === false, before)).spectator, false, 'a spectator can take a seat in the lobby');
  assert.equal(room.players.length, 2, 'the disconnected match seat was freed for the invite');
  await invite.send({ t: 'spectate' });
  assert.deepEqual([room.players.length, room.spectators.length, last(invite, 'lobby').you], [1, 1, -1], 'a seated player can step back to watch');

await connect('publicone');
entry = (await (await fetch(base + '/api/rooms')).json()).rooms[0];
assert.equal(entry.joinable, false, 'map seat capacity, not global capacity');
const late = await connect('publicone');
assert.equal(late.messages.find(m => m.t === 'lobby')?.spectator, true, 'a late join cannot overfill a listed map');
